cases.wholeExpected:
@media print, screen {
  .b {
    color: green;
  }
}

.a {
  color: red;
}

cases.originalRust:
let res = bundle(
  TestProvider {
    map: fs! {
      "/a.css": r#"
      @import "b.css" print;
      @import "b.css" screen;
      .a { color: red }
    "#,
      "/b.css": r#"
      .b { color: green }
    "#
    },
  },
  "/a.css",
);
assert_eq!(
  res,
  indoc! { r#"
  @media print, screen {
    .b {
      color: green;
    }
  }

  .a {
    color: red;
  }
"#}
);

