cases.originalRust:
let res = bundle(
  TestProvider {
    map: fs! {
      "/index.css": r#"
      @import "a.css";
      @import "b.css";
    "#,
      "/a.css": r#"
      @import "./c.css";
      body { background: red; }
    "#,
      "/b.css": r#"
      @import "./c.css";
      body { color: red; }
    "#,
      "/c.css": r#"
      body {
        background: white;
        color: black;
      }
    "#
    },
  },
  "/index.css",
);
assert_eq!(
  res,
  indoc! { r#"
  body {
    background: red;
  }

  body {
    background: #fff;
    color: #000;
  }

  body {
    color: red;
  }
"#}
);

